import { createStore } from "solid-js";

// Silent: the dead arm's `var Reflect` still declares the trap's own
// `Reflect`, `undefined` when it is read, so `Reflect.get` throws a TypeError
// and no member of the store is read. A dead arm that declares a binding
// outside itself keeps its text.
function useHoistedBaseQuery(options) {
  const [state] = createStore({ search: options.search });
  return new Proxy(state, {
    get(target, prop, receiver) {
      if (typeof window === "undefined") {
        var Reflect;
      }
      return Reflect.get(target, prop, receiver);
    }
  });
}
export function useHoistedQuery(options) {
  return useHoistedBaseQuery(options);
}
